WITH src AS (SELECT *, CAST(is_active AS INT) AS is_active_flag FROM customers WHERE (email IS NOT NULL AND email LIKE '%@mail.co.th') OR age <> 58), summary AS (SELECT DATE_FORMAT(signup_date, 'yyyy-MM') AS signup_month, COUNT(CASE WHEN segment = 'Corporate' THEN 1 END) AS corporate_count, ROUND((100 * SUM(CASE WHEN country = 'UK' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_uk FROM src GROUP BY DATE_FORMAT(signup_date, 'yyyy-MM')) SELECT signup_month, corporate_count FROM summary WHERE corporate_count < 8 ORDER BY 2 DESC, signup_month LIMIT 50
